use vstd::prelude::*;

verus! {

spec fn vec_add(a: Seq<int>, b: Seq<int>) -> Seq<int>
    recommends
        a.len() == b.len(),
{
    Seq::new(a.len(), |i: int| a[i] + b[i])
}

fn add_list(arr1: &Vec<i32>, arr2: &Vec<i32>) -> (out: Vec<i32>)
    requires
        arr1@.len() == arr2@.len(),
        // no-overflow assumption for i32 addition at each index
        forall|i: int|
            0 <= i < arr1@.len() ==>
                i32::MIN as int <= arr1@[i] + arr2@[i] <= i32::MAX as int,
    ensures
        out@.len() == arr1@.len(),
        out@ == vec_add(arr1@.map(|x: i32| x as int), arr2@.map(|x: i32| x as int))
{
    assert_eq!(arr1.len(), arr2.len(), "input arrays must have the same length");

    arr1.iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a + b) // safe under the stated no-overflow assumption
        .collect()
}

}

